CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, username VARCHAR(255) UNIQUE NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password TEXT NOT NULL, firstname VARCHAR(255), lastname VARCHAR(255), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS roles (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) UNIQUE NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS permissions (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) UNIQUE NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS user_roles (user_id BIGINT REFERENCES users(id) ON DELETE CASCADE, role_id BIGINT REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS role_permissions (role_id BIGINT REFERENCES roles(id) ON DELETE CASCADE, permission_id BIGINT REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS content_types (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) UNIQUE NOT NULL, plural_name VARCHAR(255) UNIQUE NOT NULL, api_id VARCHAR(255) UNIQUE NOT NULL, description TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS fields (id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, field_name VARCHAR(255) NOT NULL, type VARCHAR(255) NOT NULL, required BOOLEAN, "unique" BOOLEAN, target_content_type VARCHAR(255), relation_type VARCHAR(255), content_type_id BIGINT REFERENCES content_types(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS media (id BIGSERIAL PRIMARY KEY, name VARCHAR(255), alternative_text VARCHAR(255), caption TEXT, width INTEGER, height INTEGER, hash VARCHAR(255) NOT NULL, ext VARCHAR(255), mime VARCHAR(255), size NUMERIC, url TEXT, provider VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_permissions (id BIGSERIAL PRIMARY KEY, content_type_api_id VARCHAR(255) NOT NULL, endpoint VARCHAR(255) NOT NULL, method VARCHAR(16) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_permission_roles (permission_id BIGINT REFERENCES api_permissions(id) ON DELETE CASCADE, role_name VARCHAR(255) NOT NULL, PRIMARY KEY(permission_id,role_name));
CREATE TABLE IF NOT EXISTS content_permissions (id BIGSERIAL PRIMARY KEY, content_type_api_id VARCHAR(255) NOT NULL, action VARCHAR(32) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content_permission_roles (permission_id BIGINT REFERENCES content_permissions(id) ON DELETE CASCADE, role_name VARCHAR(255) NOT NULL, PRIMARY KEY(permission_id,role_name));
